// Application-owned local handler for Prompt 152.
// s is the lesson state; p contains validated classroom controls.
switch (action.op) {
    case 'webhook.process': {
        const id = p.old ? 'delivery_old' : 'delivery_new';
        const duplicate = s.seen.includes(id);
        if (!duplicate)
            s.seen.push(id);
        r.currentProjection = { status: 'idle', revision: 3 };
        accept({ deliveryId: id, duplicate, fetchedCurrentState: !duplicate, projection: r.currentProjection, reordered: !!p.old });
        break;
    }
}
